contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint lockTime, uint amount, uint collectAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount > 0);
        require(address(this).balance >= amount);

        c.Put{value: amount}(lockTime); if (__ESBMC_reverted()) return;

        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this)); if (__ESBMC_reverted()) return;

        require(beforeBalance >= collectAmount);
        require(beforeBalance >= c.MinSum());
        require(block.timestamp > beforeUnlock);
        require(address(c).balance >= collectAmount);

        uint balanceBefore = address(this).balance;

        bool reverted;
        c.Collect(collectAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        (uint afterUnlock, uint afterBalance) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        uint balanceAfter = address(this).balance;

        assert(!reverted && afterBalance == beforeBalance - collectAmount && balanceAfter == balanceBefore + collectAmount);
    }

    receive() external payable {}
}

